1: /** @module @category Store */
2: import { useCallback, useMemo, useSyncExternalStore } from 'react';
3: import type { StoreApi } from 'zustand';
4: 
5: export type ActionFunction<T> = (state: T, ...args: any[]) => Partial<T>;
6: 
7: type ActionFunctionsRecord<T> = Record<string, ActionFunction<T>>;
8: 
9: export type Actions<T> = ((store: StoreApi<T>) => ActionFunctionsRecord<T>) | ActionFunctionsRecord<T>;
10: 
11: export type BoundActions<T, A extends Actions<T>> =
12:   A extends ActionFunctionsRecord<T>
13:     ? BindFunctionsIn<A>
14:     : A extends (store: StoreApi<T>) => ActionFunctionsRecord<T>
15:       ? BindFunctionsIn<ActionFunctionsRecord<T>>
16:       : never;
17: 
18: // Given function type F, returns a new function type
19: // with F's first input argument removed and its return type set to void
20: type Bind<F extends (...args: any[]) => any> = F extends (firstArg, ...restArgs: infer RestArgsType) => any
21:   ? (...args: RestArgsType) => void
22:   : never;
23: 
24: // Given record type R, returns a new record type with Bind applied to every function in R
25: type BindFunctionsIn<R extends Record<string, (...args: any[]) => any>> = {
26:   [Prop in keyof R]: Bind<R[Prop]>;
27: };
28: 
29: function bindActions<T>(store: StoreApi<T>, actions: Actions<T>): BoundActions<T, Actions<T>> {
30:   if (typeof actions == 'function') {
31:     actions = actions(store);
32:   }
33: 
34:   const bound = {};
35: 
36:   for (const [actionName, actionFunction] of Object.entries(actions)) {
37:     const boundFunction: Bind<ActionFunction<T>> = function (...args) {
38:       store.setState((state) => {
39:         return actionFunction(state, ...args);
40:       });
41:     };
42:     bound[actionName] = boundFunction;
43:   }
44: 
45:   return bound;
46: }
47: 
48: /**
49:  * A single shared identity function, rather than one built per call: `getSnapshot` below takes
50:  * the selector as a dependency, so a fresh default each render would leave it unstable for every
51:  * caller that doesn't pass a selector of its own.
52:  */
53: const identitySelect = (x: unknown) => x;
54: 
55: const defaultSelectFunction = <T, U>() => identitySelect as (x: T) => U;
56: 
57: function useStore<T>(store: StoreApi<T>): T;
58: function useStore<T, U>(store: StoreApi<T>, select: (state: T) => U): U;
59: function useStore<T, U, A extends Actions<T>>(
60:   store: StoreApi<T>,
61:   select: undefined,
62:   actions: A,
63: ): T & BoundActions<T, A>;
64: function useStore<T, U, A extends Actions<T>>(
65:   store: StoreApi<T>,
66:   select: (state: T) => U,
67:   actions: A,
68: ): U & BoundActions<T, A>;
69: function useStore<T, U, A extends Actions<T>>(
70:   store: StoreApi<T>,
71:   select: (state: T) => U = defaultSelectFunction(),
72:   actions?: A,
73: ) {
74:   // Use useSyncExternalStore to subscribe synchronously during render
75:   // This ensures React can properly track all state updates
76:   const subscribe = useCallback(
